values ('bacc1010-2015-4000-8000-000000000002', 'kh-grade12-science-mathematics-limits-continuity', null, 2015, 'open', 'គណនាលីមីត៖
ក. $\displaystyle\lim_{x\to2}\frac{x^3-8}{\sqrt{x+2}-2}$
